const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=[['年轻女性在客厅，面对镜头介绍编程课程。','年轻女性 · 齐肩黑发 · 米色上衣','客厅','让孩子爱上编程，从核桃编程开始。','标题字幕：快乐学编程'],['孩子在桌边拼好积木车并向镜头展示。','小男孩 · 短发 · 白色上衣','客厅','边玩边学，培养动手能力。','卖点字幕：动手创造'],['手指在手机 App 中演示课程操作。','手部特写','手机界面','现在加入，开启孩子编程之旅。','引导字幕：立即体验']];
function makeTask(id,name,time){return {id,name,time,stage:'需求待填写',brief:'',parsed:false,mode:'keep',script:'',plans:['年轻女性，红色上衣；其余人物、客厅、积木车保持不变。'],shots:defaults.map((a,i)=>({id:i,description:a[0],person:a[1],scene:a[2],speech:a[3],caption:a[4],cuts:i===0?[1,2,3,4]:i===1?[5,6,7]:[8,9,10,11,12],prompt:'',ai:'',manual:false,refs:[],method:'pending',open:false,candidates:[],approved:false})),assets:[],results:[],batch:0,review:false,sampleConfirmed:false,progress:0,running:false,change:[],keep:[],excluded:[]};}
const saved=localStorage.getItem('replica-workbench-v3');let state;try{state=JSON.parse(saved)}catch{}if(!state?.tasks)state={tasks:[makeTask('t1','核桃编程',Date.now()),makeTask('t2','家居收纳',Date.now()-3600000),makeTask('t3','宠物用品',Date.now()-86400000)],assets:[{id:'a1',name:'人物参考图',type:'image',kind:0,source:'核桃编程'},{id:'a2',name:'积木车参考图',type:'image',kind:1,source:'核桃编程'}]};FAMILY_DEMO_ASSETS.forEach(a=>{const old=state.assets.find(x=>x.id===a.id);if(old)Object.assign(old,a);else state.assets.push(a)});state.assets=[...FAMILY_DEMO_ASSETS.map(a=>state.assets.find(x=>x.id===a.id)),...state.assets.filter(a=>!a.builtin||a.id.startsWith('med-'))];state.deletedTasks=state.deletedTasks||[];if(!state.tasks.some(t=>t.id==='family-demo')&&!state.deletedTasks.some(x=>(x.task?.id||x.id)==='family-demo'))state.tasks.unshift(seedFamilyTask());else{const demo=state.tasks.find(t=>t.id==='family-demo');if(demo&&demo.fixtureVersion!==4){state.previousFamilyDemo=JSON.parse(JSON.stringify(demo));const fresh=seedFamilyTask();fresh.folder=demo.folder;fresh.time=demo.time;state.tasks[state.tasks.indexOf(demo)]=fresh}}
state.tasks.forEach(t=>{t.running=false;t.assets=t.assets||[];t.excluded=t.excluded||[]});if(!state.folders){state.folders=[{id:'walnut',name:'核桃编程',open:true},{id:'beauty',name:'医美',open:true},{id:'dental',name:'牙医',open:true},{id:'other',name:'其他项目',open:false}];state.tasks.forEach(t=>t.folder=t.name.includes('核桃')?'walnut':'other')}state.tasks.forEach(t=>t.shots.forEach((s,i)=>{if(s.sourceIndex===undefined)s.sourceIndex=i}));let cutSelection=new Set(),currentFolder='walnut',materialsOpen=false;let editResult=null;let active=state.tasks.some(t=>t.id===state.activeTask)?state.activeTask:state.tasks[0]?.id||null,view='work',assetTab='finished',assetFilter='全部',assetQuery='',taskQuery='',selectedResults=new Set(),dialogCtx={},draftCuts=[],toastTimer;
const task=()=>state.tasks.find(t=>t.id===active),shot=i=>task().shots[i];currentFolder=task()?.folder||state.folders[0]?.id||'walnut';
let localSaveStatus={ok:true};
function save(){
  state.activeTask=active;
  const wasFailed=!localSaveStatus.ok;
  try{localStorage.setItem('replica-workbench-v3',JSON.stringify(state));localSaveStatus={ok:true}}
  catch{localSaveStatus={ok:false};if(!wasFailed)toast('本地保存失败，当前内容仍在页面中；可重试或导出备份')}
  document.querySelectorAll('.studio-save-state').forEach(el=>{el.textContent=localSaveStatus.ok?'已保存':'保存失败';el.classList.toggle('is-error',!localSaveStatus.ok)});
  document.querySelectorAll('.studio-save-error').forEach(el=>el.hidden=localSaveStatus.ok);
  return localSaveStatus.ok;
}
function exportWorkspaceState(){
  const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));
  const a=document.createElement('a');a.href=url;a.download='复刻大师-工作台备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function touch(){const current=task();if(current)current.time=Date.now();save()}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function art(k=0){if(k===2)return `<svg viewBox="0 0 180 320" xmlns="http://www.w3.org/2000/svg"><rect width="180" height="320" fill="#e5eaf0"/><path d="M0 250 Q80 170 180 265 V320 H0" fill="#b6c2ce"/><rect x="43" y="44" width="97" height="215" rx="14" fill="#33445c"/><rect x="50" y="57" width="83" height="186" rx="8" fill="#f8fafc"/><rect x="69" y="62" width="46" height="7" rx="4" fill="#33445c"/><rect x="60" y="91" width="63" height="51" rx="5" fill="#bbccea"/><path d="M80 125 L90 103 L104 127" stroke="#577ab5" fill="none" stroke-width="4"/><rect x="60" y="155" width="63" height="13" rx="3" fill="#d5dfec"/><rect x="60" y="182" width="44" height="9" rx="3" fill="#d5dfec"/><rect x="60" y="202" width="52" height="9" rx="3" fill="#d5dfec"/></svg>`;return `<svg viewBox="0 0 180 320" xmlns="http://www.w3.org/2000/svg"><rect width="180" height="320" fill="#e5eaf0"/><rect x="15" y="32" width="58" height="90" fill="#d4dee7"/><rect x="125" y="80" width="35" height="130" rx="3" fill="#c4cfda"/><path d="M134 80 Q110 60 136 29 Q154 56 140 80" fill="#9cafa7"/><path d="M35 270 Q25 180 90 177 Q155 178 148 276" fill="${k===1?'#fafbfd':'#c7bdb4'}"/><path d="M49 163 Q26 57 83 46 Q145 44 132 167" fill="#354151"/><ellipse cx="91" cy="113" rx="39" ry="48" fill="#dfc2ad"/><path d="M51 94 Q58 44 93 51 Q138 58 132 94 Q105 88 79 69 Q67 91 51 94" fill="#354151"/><circle cx="77" cy="113" r="2.8" fill="#354151"/><circle cx="105" cy="113" r="2.8" fill="#354151"/><path d="M79 135 Q92 146 105 134" fill="none" stroke="#9c6d5b" stroke-width="2.5"/><rect x="0" y="272" width="180" height="48" fill="#b9c5d1"/>${k===1?'<rect x="44" y="251" width="76" height="29" rx="4" fill="#6688b9"/><circle cx="58" cy="281" r="9" fill="#354151"/><circle cx="108" cy="281" r="9" fill="#354151"/>':''}</svg>`}
const kind=n=>n<5?0:n<8?1:2,secs=n=>task()?.medicalSpeechDemo?(task().medicalCutSeconds[n]||2):task()?.demoFamily?(FAMILY_CUT_SECONDS[n]||2):([7,12].includes(n)?3:2),duration=s=>s.independent?Math.round(s.sourceDuration||0):s.cuts.reduce((a,n)=>a+secs(n),0),media=t=>t.assets.map(id=>state.assets.find(a=>a.id===id)).find(a=>a?.type==='video');
function preview(k,d,action='preview',i=0,url){return `<button class="preview" data-action="${action}" data-i="${i}" aria-label="预览${d?'分镜':''}">${url?`<img src="${esc(url)}" alt="素材预览">`:action==='cutPreview'&&task()?.demoFamily?assetVisual(state.assets.find(a=>a.id===(task().shots.find(s=>s.cuts.includes(i))?.thumb||'family-image-2')),'shot-photo'):art(k)}<span class="play">▶</span>${d?`<span class="duration">${d} 秒</span>`:''}</button>`}
function uiIcon(name){const paths={brand:'<rect x="4" y="4" width="12" height="12" rx="3"/><path d="M9 9h11v11H9V9Z"/><path d="m13 12 4 3-4 3z"/>',work:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M3 10h18M9 10v10"/>',assets:'<path d="M3 7h7l2 2h9v10H3V7Z"/><path d="M3 7V4h7l2 2h9v3"/>',plus:'<path d="M12 5v14M5 12h14"/>',down:'<path d="m6 9 6 6 6-6"/>',up:'<path d="m6 15 6-6 6 6"/>',undo:'<path d="M3 10h11a6 6 0 0 1 0 12M3 10l5-5M3 10l5 5"/>',edit:'<path d="m15 4 5 5-11 11H4v-5L15 4Z"/>',trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v6M14 11v6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',locate:'<path d="M12 3v3M12 18v3M3 12h3M18 12h3"/><circle cx="12" cy="12" r="6"/>',play:'<path d="m8 5 11 7-11 7V5Z"/>',resume:'<path d="M5 7a8 8 0 1 1-1 9M5 3v5h5"/><path d="m11 8 5 4-5 4z"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',link:'<path d="m10 14 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 0 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>'};return `<svg class="ui-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.work}</svg>`}
function header(){return `<header><div class="brand"><span class="brand-mark">${uiIcon('brand')}</span>复刻大师 <em>2.0</em></div><nav aria-label="主导航"><button data-action="view" data-view="work" class="${view==='work'?'active':''}">${uiIcon('work')}工作台</button><button data-action="view" data-view="assets" class="${view==='assets'?'active':''}">${uiIcon('assets')}资产库</button></nav><span class="demo">交互原型 · AI 解析与生成使用演示数据</span><button class="link small" data-action="reset">重置演示</button></header>`}
function sidebar(){const sorted=[...state.tasks].sort((a,b)=>b.time-a.time);return `<aside class="task-sidebar"><div class="aside-head"><span>项目文件夹</span><button class="link small" data-action="newFolder">＋ 文件夹</button></div><button class="primary upload-entry" data-action="newTask">↑ 上传视频</button><p class="upload-destination">添加到 ${esc(state.folders.find(f=>f.id===currentFolder)?.name||'当前项目')}</p><input class="search" aria-label="搜索任务" placeholder="搜索任务名称" value="${esc(taskQuery)}" data-field="taskQuery">${state.folders.map(f=>{const tasks=sorted.filter(t=>t.folder===f.id&&t.name.includes(taskQuery));return `<div class="folder" data-folder="${f.id}"><button class="folder-head ${currentFolder===f.id?'selected':''}" data-action="folder" data-id="${f.id}" aria-expanded="${f.open||!!taskQuery}"><span>${f.open||taskQuery?'⌄':'›'} ▱ ${esc(f.name)}</span><small>${tasks.length}</small></button>${f.open||taskQuery?tasks.map(t=>`<button class="task ${t.id===active?'active':''}" data-action="task" data-id="${t.id}" draggable="true" aria-label="${esc(t.name)}，可拖动到其他项目"><span class="drag-handle" aria-hidden="true">⠿</span><b>${esc(t.name)}</b><small><i class="dot"></i>${esc(t.stage)}</small>${t.results.length?`<small>待预览 ${t.results.filter(r=>r.status==='待预览').length} / 已选用 ${t.results.filter(r=>r.status==='已选用').length}</small>`:''}</button>`).join('')||'<p class="folder-empty">暂无任务</p>':''}</div>`}).join('')}${state.undoTaskMove?'<button class="link small" data-action="undoTaskMove">↶ 撤销任务移动</button>':''}<div class="aside-note">拖动任务可移动到其他项目<br>项目内最新任务在最上面</div></aside>`}
function taskMaterials(t){return `<button class="materials-toggle" data-action="toggleMaterials">▧ 任务素材</button><section class="task-materials ${materialsOpen?'open':''}" aria-label="任务内素材库"><div class="row between"><h2>任务素材</h2><button class="material-close link small" data-action="toggleMaterials" aria-label="收起任务素材">×</button><span class="small muted">${refs(t).filter(a=>a.type==='image'&&a.role!=='原片记录').length} 张</span></div><p class="small muted">悬停放大 · 提示词输入 @ 引用</p><button class="material-add" data-action="materials" data-i="-1">＋ 添加参考图片</button><div class="material-tiles">${refs(t).filter(a=>a.type==='image'&&a.role!=='原片记录').map(a=>`<div class="material-tile"><button class="material-image" data-action="assetPreview" data-i="${a.id}" aria-label="查看${esc(a.name)}">${a.builtin?assetVisual(a):`<img src="${esc(a.url)}" alt="${esc(a.name)}">`}</button><span>${esc(a.name)}</span><div class="material-hover">${a.builtin?assetVisual(a):`<img src="${esc(a.url)}" alt="${esc(a.name)}">`}<b>${esc(a.name)}</b></div><button class="material-remove" data-action="unref" data-id="${a.id}" aria-label="移除${esc(a.name)}">×</button></div>`).join('')}</div></section>`}
function refs(t){return (t?.assets||[]).map(id=>state.assets.find(a=>a.id===id)).filter(Boolean)}
function mentions(i){return `<div class="mention-list"><span class="small muted">选择图片引用：</span>${refs(task()).filter(a=>a.type==='image'&&a.role!=='原片记录').map(a=>`<button data-action="mention" data-i="${i}" data-id="${a.id}">${a.builtin?assetVisual(a,'mention-thumb'):''}<span>${i>=0&&task().demoFamily?'@图片'+(shot(i).refs.includes(a.id)?shot(i).refs.indexOf(a.id)+1:shot(i).refs.length+1):'@'+esc(a.name)} · ${esc(a.name)}<small>${esc(a.tags||'图片参考')}</small></span></button>`).join('')}<button data-action="materials" data-i="${i}">＋ 添加素材</button></div>`}
function brief(t){return `<section class="panel brief"><div class="row between brief-label"><h2>模糊需求 · 告诉我想怎么改</h2><div class="row wrap">${t.demoFamily?'<button class="brief-example" data-action="fillDemo">填入示例需求</button>':''}<span class="badge ${t.parsed?'green':'blue'}">${t.parsed?'需求已解析':'一次输入，填写所有分镜提示词'}</span></div></div><textarea aria-label="全片改编需求" data-field="brief" placeholder="例如：把女主的上衣换成红色，使用 @人物参考图，保留客厅、积木车和口播。帮我做 3 条不同服装的版本。">${esc(t.brief)}</textarea>${t.brief.endsWith('@')?mentions(-1):''}<div class="row between wrap brief-footer"><div class="row wrap"><label class="small">口播 <select data-field="mode" aria-label="口播模式"><option value="keep" ${t.mode==='keep'?'selected':''}>不改口播</option><option value="replace" ${t.mode==='replace'?'selected':''}>替换口播</option></select></label><button data-action="plans">方案 ${t.plans.length} 条 · 含 1 条样片</button><button class="link" data-action="materials" data-i="-1">＋ 添加 / 引用素材</button></div><button class="primary" data-action="parse" ${t.running?'disabled':''}>${t.parsed?'重新解析需求':'解析需求并填写提示词'}</button></div>${t.mode==='replace'?`<div style="margin-top:12px"><label class="small">完整新口播</label><textarea data-field="script" aria-label="完整新口播" placeholder="填写整条视频的新台词，系统将分配到分镜。">${esc(t.script)}</textarea></div>`:''}${t.parsed?`<details class="parse-summary"><summary>已解析修改项与保留项 · 展开核对</summary><div class="summary"><div><b>要修改</b><ul>${t.change.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></div><div><b>要保持</b><ul>${t.keep.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></div></div></details>`:''}</section>`}
function shotCard(s,t){return `<article class="shot" id="shot-${s.id}"><div>${t.demoFamily?`<button class="preview" data-action="preview" data-i="${s.id}" aria-label="预览分镜${s.id+1}">${assetVisual(state.assets.find(a=>a.id===s.thumb),'shot-photo')}<span class="play">▶</span><span class="duration">${duration(s)} 秒</span></button>`:preview(s.id,duration(s),'preview',s.id)}<p class="small muted" style="text-align:center">${t.demoFamily?'案例画面示意 · 非视频':'原片分镜预览'}</p>${s.candidates.length?`<button style="width:100%" class="small" data-action="candidates" data-i="${s.id}">候选 ${s.candidates.length} 个</button>`:''}</div><div><div class="row between shot-head"><div class="row"><b>分镜 ${String(s.id+1).padStart(2,'0')}</b><span class="badge">${duration(s)} 秒</span>${s.approved?'<span class="badge green">样片已通过</span>':''}</div><div class="row"><select aria-label="分镜处理方式" ${!t.parsed?'disabled':''} data-field="method" data-i="${s.id}"><option value="pending" disabled ${s.method==='pending'?'selected':''}>待解析需求</option><option value="edit" ${s.method==='edit'?'selected':''}>视频编辑</option><option value="aigc" ${s.method==='aigc'?'selected':''}>AIGC 生成</option><option value="keep" ${s.method==='keep'?'selected':''}>使用原片</option></select><button class="link small" data-action="moveShot" data-i="${s.id}" data-direction="-1" aria-label="上移分镜${s.id+1}" ${s.id===0?'disabled':''}>↑</button><button class="link small" data-action="moveShot" data-i="${s.id}" data-direction="1" aria-label="下移分镜${s.id+1}" ${s.id===t.shots.length-1?'disabled':''}>↓</button><button class="link small danger" data-action="deleteShot" data-i="${s.id}" aria-label="删除分镜${s.id+1}">删除</button><button class="link small" data-action="toggleCuts" data-i="${s.id}">${s.open?'收起调整 ⌃':'调整细分镜 ⌄'}</button></div></div><div class="description"><input class="edit-inline" data-field="description" data-i="${s.id}" aria-label="画面描述" value="${esc(s.description)}"><div class="facts"><label><span>人物</span><input class="edit-inline" style="width:220px" data-field="person" data-i="${s.id}" aria-label="人物" value="${esc(s.person)}"></label><label><span>场景</span><input class="edit-inline" style="width:100px" data-field="scene" data-i="${s.id}" aria-label="场景" value="${esc(s.scene)}"></label></div><div class="facts"><label style="flex:1"><span>口播转写</span><textarea class="edit-inline speech-record" data-field="speech" data-i="${s.id}" aria-label="口播转写" rows="${t.demoFamily?3:1}">${esc(s.speech)}</textarea></label><label style="flex:1"><span>其他字幕</span><input class="edit-inline" data-field="caption" data-i="${s.id}" aria-label="其他字幕识别记录" value="${esc(s.caption)}"></label></div></div>${s.open?cutPanel(s):''}${s.needsReview?'<p class="notice">片段已调整，请核对本镜描述、台词及提示词的修改范围。</p>':''}<div class="edit-pair"><div><div class="field-head"><span>分镜提示词 ${s.manual?'<span class="badge amber">手动编辑</span>':''}</span><div class="row"><button class="link small" data-action="addMention" data-i="${s.id}">@ 图片</button><button class="small" data-action="polish" data-i="${s.id}" ${!t.parsed||s.method==='keep'?'disabled':''}>✦ AI 润色</button>${s.undoPrompt!==undefined?`<button class="link small" data-action="undoPrompt" data-i="${s.id}">撤销润色</button>`:''}${t.review?`<button class="link small" data-action="redo" data-i="${s.id}">重做此镜</button>`:''}</div></div><textarea class="prompt" data-field="prompt" data-i="${s.id}" aria-label="分镜${s.id+1}提示词" placeholder="${s.method==='keep'?'使用原片，无需生成提示词':'解析模糊需求后，系统会自动填写提示词'}" ${!t.parsed||s.method==='keep'?'disabled':''}>${esc(s.prompt)}</textarea>${s.prompt.endsWith('@')?mentions(s.id):''}${t.parsed&&s.method==='edit'?'<p class="small muted">@视频1 = 当前分镜的编辑母版；图片编号仅作用于此镜</p>':''}<div class="row wrap">${s.refs.map(id=>state.assets.find(a=>a.id===id)).filter(Boolean).map(a=>`<span class="ref">${a.type==='image'&&a.url?`<button class="ref-preview" data-action="assetPreview" data-i="${a.id}" aria-label="查看${esc(a.name)}">${assetVisual(a,'mini')}</button>`:''}${t.demoFamily?'@图片'+(s.refs.indexOf(a.id)+1)+' · ': '@'}${esc(a.name)}<button class="link" data-action="removeMention" data-i="${s.id}" data-id="${a.id}">×</button></span>`).join('')}</div>${s.suggestion?`<div class="suggestion"><b>润色建议</b><p>${esc(s.suggestion)}</p><button class="primary small" data-action="apply" data-i="${s.id}">应用到提示词</button><button class="link small" data-action="discard" data-i="${s.id}">放弃</button></div>`:''}</div></div>${s.method==='keep'?'<p class="small muted">沿用原片画面，不调用生成；替换口播模式下此镜静音。</p>':''}${duration(s)<4&&s.method!=='keep'?'<p class="notice">此镜按 4 秒重新生成，成片会变长。</p>':''}</div></article>`}
function cutPanel(s){const selected=s.cuts.filter(n=>cutSelection.has(n));return `<div class="cuts"><div class="row between wrap"><b class="small">组成片段 ${s.cuts.length} 个</b><div class="row"><button class="small" data-action="selectCuts" data-i="${s.id}">${selected.length===s.cuts.length?'取消全选':'全选片段'}</button><button class="link small" data-action="undoCuts" ${!task().undoCuts?'disabled':''}>↶ 撤销调整</button></div></div><div class="cut-list">${s.cuts.map(n=>`<div class="cut ${cutSelection.has(n)?'chosen':''}"><label class="cut-check"><input type="checkbox" aria-label="选择片段${n}" data-field="mergeCutSelect" data-n="${n}" ${cutSelection.has(n)?'checked':''}></label><button class="remove" aria-label="移除片段${n}" data-action="removeCut" data-i="${s.id}" data-n="${n}">×</button>${preview(kind(n),0,'cutPreview',n)}<div>${String(n).padStart(2,'0')} · ${secs(n)} 秒</div></div>`).join('')}<button class="add-cut" data-action="moveCuts" data-i="${s.id}">＋<br>增加细分镜</button></div><div class="row between wrap"><span class="small muted">选中的片段移入新分镜，原分镜同步更新</span><button class="primary small" data-action="mergeNew" data-i="${s.id}" ${selected.length<2?'disabled':''}>合并为新分镜${selected.length?'（'+selected.length+'）':''}</button></div></div>`}
function review(t){if(!t.review&&!t.running)return '';return `<section class="panel" id="sample-review"><div class="row between"><h2>${t.running?'正在生成':'完整样片审核'}</h2><span class="badge blue">${t.running?`${t.progress} / ${t.shots.filter(s=>s.cuts.length).length} 镜完成`:'样片计入总数'}</span></div>${t.running?`<div class="progress-track"><i style="width:${t.progress/t.shots.filter(s=>s.cuts.length).length*100}%"></i></div><p class="muted small">${esc(t.runLabel||'逐镜生成 → 自动合成')} · 演示进度</p>`:`<div class="review" style="margin-top:15px"><div>${preview(0,t.shots.reduce((n,s)=>n+duration(s),0),'samplePreview',0)}<p class="small muted">模拟样片 · ${[...t.results].reverse().find(r=>r.sample&&r.batch===t.batch)?.current||'v1'}</p></div><div><p class="muted">先预览完整样片，再确认每个分镜；有问题可在下方修改提示词、重做。</p>${t.shots.filter(s=>s.cuts.length).map(s=>`<div class="check-row"><span>分镜 ${s.id+1} <span class="badge ${s.approved?'green':''}">${s.approved?'通过':'待审核'}</span></span><div><button class="link" data-action="locate" data-i="${s.id}">定位</button><button data-action="approveShot" data-i="${s.id}" data-value="${!s.approved}">${s.approved?'改为待修改':'通过'}</button></div></div>`).join('')}<div class="row wrap" style="margin-top:16px">${!t.sampleConfirmed?`<button class="primary" data-action="confirmSample" ${t.shots.filter(s=>s.cuts.length).some(s=>!s.approved)?'disabled':''}>确认完整样片</button>`:`<span class="badge green">完整样片已确认</span>${t.plans.length>1?`<button class="primary" data-action="batch">批量生成剩余 ${t.plans.length-1} 条</button>`:'<button data-action="goFinished">查看 / 下载成片</button>'}`}</div></div></div>`}</section>`}
function work(){const t=task();return `<main><div class="row between"><div><h1>${esc(t.name)}</h1><span class="muted small">工作台 · ${esc(t.stage)} · 自动保存</span></div>${t.sourceUrl?`<a class="source-link" href="${esc(t.sourceUrl)}" target="_blank" rel="noopener noreferrer">↗ 原视频链接</a>`:'<button class="link" data-action="original">▶ 查看原视频</button>'}</div>${brief(t)}${review(t)}<div class="section-title"><h2>分镜与提示词 <span class="muted small">${t.shots.filter(s=>s.cuts.length).length} 个分镜 · 每镜一种生成方式</span></h2><div class="row"><button data-action="undoCuts" ${!t.undoCuts?'disabled':''}>↶ 撤销调整</button><button class="primary" data-action="addShot">＋ 新增分镜</button></div></div>${t.shots.map(s=>shotCard(s,t)).join('')}<div class="bottom row between"><span class="muted small">${t.parsed?`${t.plans.length} 条方案，先生成 1 条完整样片`:'输入需求后，系统会填写每镜提示词'} · 分镜调整按需进行</span><button class="primary" data-action="generate" ${t.running?'disabled':''}>${t.review?'按当前要求新建批次':'生成完整样片'}</button></div></main>`}
function allResults(){return state.tasks.flatMap(t=>t.results.map(r=>({...r,taskId:t.id,taskName:t.name})))}
function assets(){const list=assetTab==='finished'?allResults().filter(r=>(assetFilter==='全部'?r.status!=='废弃':r.status===assetFilter)&&(`${r.taskName} ${r.name}`.includes(assetQuery))):state.assets.filter(a=>a.type==='image'&&a.role!=='原片记录'&&(assetFilter==='全部'||a.type==='image')&&(`${a.name} ${a.source}`.includes(assetQuery)));return `<main><div class="row between"><div><h1>资产库</h1><p class="muted small">完整成片与可复用素材，统一保存在这里</p></div>${assetTab==='raw'?'<button class="primary" data-action="uploadAssets">上传参考图片</button>':''}</div><div class="row between wrap section-title"><div class="tabs"><button class="${assetTab==='finished'?'active':''}" data-action="assetTab" data-tab="finished">成片</button><button class="${assetTab==='raw'?'active':''}" data-action="assetTab" data-tab="raw">原料素材</button></div><input placeholder="搜索名称 / 来源任务" aria-label="搜索资产" value="${esc(assetQuery)}" data-field="assetQuery"></div><div class="row wrap">${(assetTab==='finished'?['全部','待审核','已定稿','待修改','废弃']:['全部','图片']).map(f=>`<button class="${assetFilter===f?'primary':''} small" data-action="filter" data-filter="${f}">${f}</button>`).join('')}${assetTab==='finished'?`<span class="muted small">已选 ${selectedResults.size} 条</span><button data-action="selectVisible">全选当前结果</button><button data-action="bulkApprove" ${!selectedResults.size?'disabled':''}>批量定稿</button><button data-action="download" ${!selectedResults.size?'disabled':''}>下载演示说明（${selectedResults.size}）</button>`:''}</div><div class="asset-grid">${list.map(a=>assetTab==='finished'?`<article class="asset-card"><div class="row between"><label><input type="checkbox" data-field="resultCheck" data-id="${a.id}" ${selectedResults.has(a.id)?'checked':''}> 选择</label><span class="badge ${a.status==='已定稿'?'green':'blue'}">${esc(a.status)}</span></div>${preview(0,26,'resultPreview',a.id)}<h3>${esc(a.name)} ${esc(a.current)}</h3><p class="muted small">${esc(a.taskName)} · 批次 ${a.batch}</p><div class="row wrap"><select data-field="status" data-id="${a.id}" aria-label="成片审核标签">${['待审核','已定稿','待修改','废弃'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select><button data-action="history" data-id="${a.id}">版本</button><button class="link" data-action="returnResult" data-id="${a.id}">返工</button></div></article>`:`<article class="asset-card">${a.builtin?`<button class="asset-image-button" data-action="assetPreview" data-i="${a.id}" aria-label="预览${esc(a.name)}">${assetVisual(a)}</button>`:preview(a.kind,0,'assetPreview',a.id,a.type==='image'?a.url:null)}<h3>${esc(a.name)}</h3><p class="small muted">${esc(a.tags||'')}</p><p class="muted small">${a.type==='image'?'图片':'视频'} · 来源：${esc(a.source)}</p><button data-action="attachAsset" data-id="${a.id}" ${!task()?'disabled':''}>添加到当前任务</button></article>`).join('')}</div>${!list.length?'<div class="empty">暂无匹配资产，请清除筛选或上传素材。</div>':''}</main>`}
function emptyWorkspace(){return '<main class="wf-main tm-empty-workspace"><h1>开始一个新任务</h1><p class="muted">上传视频开始制作，也可以恢复回收站中的任务。</p><div class="row wrap"><button class="primary" data-action="newTask">↑ 上传视频</button><button data-bp-action="newTrial">从头体验示例</button></div></main>'}
function render(){const focused=document.activeElement,field=focused?.dataset?.field,i=focused?.dataset?.i,sel=focused?.selectionStart;$('#app').innerHTML=header()+`<div class="shell">${sidebar()}${view==='work'?'<div class="work-layout">'+(task()?work()+taskMaterials(task()):emptyWorkspace())+'</div>':assets()}</div>`;if(field){const e=$(`[data-field="${field}"]${i!==undefined?`[data-i="${i}"]`:''}`);if(e){e.focus();if(typeof sel==='number'&&e.setSelectionRange)e.setSelectionRange(sel,sel)}}}
function modal(title,body,footer=''){const d=$('#dialog');d.innerHTML=`<div class="dialog-head row between"><h2>${title}</h2><button class="close ui-btn ui-btn-ghost ui-btn-icon" data-action="close" aria-label="关闭弹窗">${uiIcon('close')}</button></div><div class="dialog-body">${body}</div><div class="dialog-footer">${footer||'<span></span><button data-action="close">关闭</button>'}</div>`;if(!d.open)d.showModal()}
function uploadTaskModal(){modal('上传视频',`<p class="muted small">添加到项目：${esc(state.folders.find(f=>f.id===currentFolder)?.name)} · 上传后创建任务并自动解析</p><div class="video-import-options"><label class="local-video-option"><span class="import-icon">↑</span><b>上传本地视频</b><span>选择电脑中的视频文件</span><input type="file" accept="video/*" data-upload="template" aria-label="上传本地视频"></label><form class="link-video-option" id="video-link-form"><span class="import-icon">↗</span><b>导入视频链接</b><label for="video-link">粘贴抖音等视频分享链接</label><textarea id="video-link" rows="3" placeholder="粘贴视频链接或完整分享文字"></textarea><p class="small muted">演示：保存链接并创建任务，暂不下载平台视频</p><button type="submit" class="primary">导入并新建任务</button></form></div>`)}
function extractVideoLink(raw){const match=raw.match(/https?:\/\/[^\s<>"'，。]+/i);if(!match)return null;try{const url=new URL(match[0]);return ['http:','https:'].includes(url.protocol)?url.href:null}catch{return null}}
function createLinkTask(){const sourceUrl=extractVideoLink($('#video-link').value.trim());if(!sourceUrl)return toast('请输入有效的 http / https 视频链接');const host=new URL(sourceUrl).hostname;const name=(host.includes('douyin')?'抖音':host.includes('kuaishou')?'快手':host.includes('bilibili')?'哔哩哔哩':'链接视频')+' · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});const t=makeTask('t'+Date.now(),name,Date.now());t.folder=currentFolder;t.sourceUrl=sourceUrl;t.stage='链接已导入 · 演示分镜';state.folders.find(f=>f.id===currentFolder).open=true;state.tasks.unshift(t);active=t.id;view='work';editResult=null;save();$('#dialog').close();render();toast('已通过链接新建任务（模拟解析）')}
document.addEventListener('submit',e=>{if(e.target.id==='video-link-form'){e.preventDefault();createLinkTask()}});
let draggingTask=null,keyboardFolderIndex=-1;
function clearFolderDrag(){document.querySelectorAll('.folder.drop-target,.task.dragging').forEach(e=>e.classList.remove('drop-target','dragging'));draggingTask=null;keyboardFolderIndex=-1}
function moveTaskToFolder(id,folderId){const moved=state.tasks.find(t=>t.id===id),folder=state.folders.find(f=>f.id===folderId);if(!moved||!folder)return false;if(moved.folder===folderId){clearFolderDrag();return false}state.undoTaskMove={id,folder:moved.folder,time:moved.time};moved.folder=folderId;moved.time=Date.now();folder.open=true;currentFolder=folderId;clearFolderDrag();save();render();toast('已移动到「'+folder.name+'」');return true}
document.addEventListener('dragstart',e=>{const card=e.target.closest('.task[data-id]');if(!card)return;draggingTask=card.dataset.id;card.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',draggingTask)});
document.addEventListener('dragover',e=>{const folder=e.target.closest('.folder[data-folder]');if(!folder||!draggingTask)return;e.preventDefault();e.dataTransfer.dropEffect='move';document.querySelectorAll('.folder.drop-target').forEach(x=>x.classList.remove('drop-target'));folder.classList.add('drop-target')});
document.addEventListener('dragleave',e=>{const folder=e.target.closest('.folder[data-folder]');if(folder&&!folder.contains(e.relatedTarget))folder.classList.remove('drop-target')});
document.addEventListener('drop',e=>{const folder=e.target.closest('.folder[data-folder]');if(!folder||!draggingTask)return;e.preventDefault();moveTaskToFolder(draggingTask,folder.dataset.folder);clearFolderDrag()});
document.addEventListener('dragend',clearFolderDrag);
document.addEventListener('keydown',e=>{const card=e.target.closest('.task[data-id]');if(!card)return;if(!draggingTask&&e.key===' '){e.preventDefault();draggingTask=card.dataset.id;keyboardFolderIndex=state.folders.findIndex(f=>f.id===state.tasks.find(t=>t.id===draggingTask).folder);card.classList.add('dragging');toast('↑↓ 选择项目，Enter 移动，Esc 取消');return}if(!draggingTask)return;if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();keyboardFolderIndex=(keyboardFolderIndex+(e.key==='ArrowDown'?1:-1)+state.folders.length)%state.folders.length;document.querySelectorAll('.folder.drop-target').forEach(x=>x.classList.remove('drop-target'));$('[data-folder="'+state.folders[keyboardFolderIndex].id+'"]').classList.add('drop-target');toast('移到「'+state.folders[keyboardFolderIndex].name+'」 · Enter 确认')}else if(e.key==='Enter'||e.key===' '){e.preventDefault();moveTaskToFolder(draggingTask,state.folders[keyboardFolderIndex].id);clearFolderDrag()}else if(e.key==='Escape'){e.preventDefault();clearFolderDrag();toast('已取消移动')}});
function materialModal(i=-1){dialogCtx={type:'materials',i};modal('添加原料素材',`<label class="upload-label">上传参考图片<input type="file" accept="image/*" multiple data-upload="asset"></label><p class="small muted">只建立任务引用；图片可在提示词里通过 @ 使用。</p><div class="asset-grid">${state.assets.filter(a=>a.type==='image'&&a.role!=='原片记录').map(a=>`<article class="asset-card">${a.builtin?assetVisual(a):''}<h3>${esc(a.name)}</h3><p class="small muted">${esc(a.tags||'')}</p><p class="muted small">${a.type==='image'?'图片':'视频'} · ${esc(a.source)}</p><button data-action="attachAsset" data-id="${a.id}" ${!task()?'disabled':''}>添加到任务</button></article>`).join('')}</div>`)}
function plansModal(){dialogCtx={type:'plans'};modal('生成方案 · 一条方案对应一条完整视频',`<p class="muted small">方案 01 默认用于样片，样片计入总数量。提交后锁定本批次方案。</p><div id="plan-list">${task().plans.map((p,i)=>`<div class="plan-row"><div class="row between"><b>方案 ${String(i+1).padStart(2,'0')} ${i===0?'· 样片':''}</b>${i?`<button class="link danger" data-action="deletePlan" data-i="${i}">删除</button>`:''}</div><input data-field="plan" data-i="${i}" aria-label="方案${i+1}变化要求" value="${esc(p)}"></div>`).join('')}</div>`,`<button data-action="addPlan">＋ 新增方案</button><button class="primary" data-action="close">完成配置</button>`)}
function cutsModal(i){dialogCtx={type:'cuts',i};draftCuts=[];drawCutsModal()}
function drawCutsModal(){const s=dialogCtx.type==='newCuts'?{cuts:[],id:-1}:shot(dialogCtx.i), all=[...s.cuts,...draftCuts].sort((a,b)=>a-b);modal(dialogCtx.type==='newCuts'?'选择片段，创建新分镜':`为分镜 ${dialogCtx.i+1} 增加细分镜`,`<p class="muted">可多选片段。已属于其他分镜的片段会直接移入，无需先去原分镜删除。</p><div class="clip-grid" style="margin-top:15px">${Array.from({length:task().demoFamily?23:12},(_,j)=>j+1).map(n=>{const included=s.cuts.includes(n),chosen=draftCuts.includes(n),available=true,owner=task().shots.find(x=>x.cuts.includes(n));return `<label class="clip-option ${chosen?'selected':''} ${included||!available?'disabled':''}"><input type="checkbox" data-field="cutSelect" data-n="${n}" ${chosen?'checked':''} ${included||!available?'disabled':''}>${preview(kind(n),0,'cutPreview',n)}<p>片段 ${String(n).padStart(2,'0')} · ${secs(n)} 秒</p><span class="badge">${included?'已包含':chosen?'待移入':available?'可选择':'非相邻片段'}</span><p class="small muted">${owner?`来自分镜 ${owner.id+1}`:'已从成片移除'}</p></label>`}).join('')}</div><div class="notice" style="margin-top:15px">当前分镜：${duration(s)} → ${duration(s)+draftCuts.reduce((a,n)=>a+secs(n),0)} 秒。${task().shots.filter(x=>x.id!==s.id&&x.cuts.some(n=>draftCuts.includes(n))).map(x=>`分镜 ${x.id+1}：${duration(x)} → ${x.cuts.filter(n=>!draftCuts.includes(n)).reduce((a,n)=>a+secs(n),0)} 秒。`).join('')}<br>原分镜变空时自动移除；所选片段按原视频顺序排列，可撤销。</div>`,`<span>已选 ${draftCuts.length} 个片段</span><div class="row"><button data-action="close">取消</button><button class="primary" data-action="commitCuts" ${!draftCuts.length?'disabled':''}>${dialogCtx.type==='newCuts'?'创建新分镜':'移入当前分镜'}</button></div>`)}
function reindexShots(){const map=new Map(task().shots.map((s,i)=>[s.id+1,i+1]).filter(([old])=>old>0));task().shots.forEach((s,i)=>{for(const key of ['prompt','undoPrompt','suggestion'])if(s[key])s[key]=s[key].replace(/分镜\s*(\d+)/g,(m,n)=>map.has(+n)?'分镜'+map.get(+n):m);s.id=i})}
function familyPromptForShot(s){return familyPrompt(s.sourceIndex).replace(/分镜\s*(\d+)/g,(m,n)=>{const target=task().shots.find(x=>x.sourceIndex===+n-1);return target?'分镜'+(target.id+1):'原分镜'+n})}
function createShotFromCuts(cuts,position){const t=task(),selected=[...cuts].sort((a,b)=>a-b),owners=t.shots.filter(s=>s.cuts.some(n=>selected.includes(n)));const base=owners[0]||makeTask('','','').shots[0];const fresh=JSON.parse(JSON.stringify(base));fresh.id=-1;fresh.uid=workflowId();fresh.independent=false;delete fresh.selectedVersion;delete fresh.sourceAssetId;delete fresh.sourcePoster;delete fresh.sourceDuration;delete fresh.specKey;fresh.cuts=selected;fresh.needsReview=true;fresh.open=true;fresh.manual=true;fresh.approved=false;fresh.parts=[];fresh.candidates=[];fresh.method=t.parsed?'edit':'pending';fresh.description=owners.length?owners.map(s=>s.description).join('；'):'新增分镜：请核对画面描述';fresh.speech=owners.map(s=>s.speech).join('\n');fresh.prompt='@视频1为所选片段按原顺序组合的编辑母版。请核对本镜的编辑范围、人物绑定与台词。';fresh.refs=[];delete fresh.undoPrompt;delete fresh.suggestion;fresh.sourceIndex=null;t.shots.forEach(s=>{s.cuts=s.cuts.filter(n=>!selected.includes(n));if(owners.includes(s)){s.manual=true;s.parts=[];if(s.method==='mixed')s.method='edit';s.needsReview=true}});t.shots.splice(position,0,fresh);t.shots=t.shots.filter(s=>s.independent||s.cuts.length);t.excluded=t.excluded.filter(n=>!selected.includes(n));cutSelection.clear();reindexShots()}
function snapshotCuts(){task().undoCuts={shots:JSON.parse(JSON.stringify(task().shots)),excluded:[...task().excluded]}}
function contentChanged(){const t=task();t.sampleConfirmed=false;t.shots.forEach(s=>s.approved=false);t.stage='分镜已调整，需重新生成';touch()}
function promptFor(s){const t=task();if(t.demoFamily&&s.specKey)return singleMethodPrompt(s)+'\n\n【当前镜头识别记录】'+s.description;return `${s.description}\n人物：${s.person}；场景：${s.scene}。\n改编要求：${s.requirement||t.brief||'保持原画面主体与动作'}\n${t.mode==='replace'?`新口播：${s.newSpeech||t.script}`:`保留模板口播与音轨：${s.speech}`}\n保持未要求改变的动作、商品和场景关系。${s.method==='aigc'?'不生成画面字幕。':'保留原片已有字幕。'} 时长 ${Math.max(s.method==='keep'?0:4,duration(s))} 秒，画幅 9:16。`}
function parse(){const t=task();if(t.demoFamily)return parseFamilyDemo();if(!t.brief.trim())return toast('请先输入总需求');if(t.mode==='replace'&&!t.script.trim())return toast('替换口播时，请填写完整新台词');t.parsed=true;t.change=[`${t.brief}（演示解析，请核对）`];t.keep=['未明确修改的人物动作、场景与商品关系',t.mode==='keep'?'模板口播与音轨':'未要求修改的原片画面信息'];const clauses=t.script.split(/[。！？\n]+/).filter(Boolean);let preserved=0;t.shots.forEach((s,i)=>{if(!s.manual)s.method=t.mode==='replace'?'aigc':'edit';s.newSpeech=clauses[i]||'';s.requirement=t.brief;if(/女主|女性|上衣|服装/.test(t.brief)){s.requirement=i===0?t.brief.replace(/做\s*\d+\s*条[^。]*[。]?/g,''):'保持当前分镜人物、动作、场景与道具；女主服装要求不作用于此镜。';}const mentioned=state.assets.filter(a=>a.type==='image'&&t.brief.includes('@'+a.name));if(i===0&&mentioned.length){mentioned.forEach(a=>{if(!t.assets.includes(a.id))t.assets.push(a.id);if(!s.refs.includes(a.id))s.refs.push(a.id)})}if(!s.manual)s.prompt=promptFor(s);else preserved++});const count=t.brief.match(/(\d+)\s*[条个]/);if(count){const n=Math.min(12,Math.max(1,Number(count[1])));while(t.plans.length<n)t.plans.push(`方案 ${t.plans.length+1}：女主改为${['蓝色','绿色','白色'][t.plans.length%3]}上衣，保持其他人物、客厅、积木车与口播。`)}t.stage='需求与方案待确认';touch();render();toast(preserved?`已解析；${preserved} 个手动提示词保留，请核对`:'已填写全部分镜提示词，请核对修改项和保持项')}
function resultById(id){for(const t of state.tasks){const r=t.results.find(r=>r.id===id);if(r)return {t,r}}}
function newResult(t,n,sample=false){const r={id:`r${Date.now()}-${n}`,name:`方案 ${String(n+1).padStart(2,'0')}`,batch:t.batch,current:'v1',status:'待审核',sample,versions:[{name:'v1',status:'待审核',created:Date.now()}]};t.results.push(r);return r}
async function generate(batch=false){const t=task();if(t.running)return;editResult=null;if(batch){if(!t.sampleConfirmed||t.shots.some(s=>s.cuts.length&&!s.approved))return toast('先完成样片逐镜审核和整片确认');if(t.batchDone)return toast('本批次剩余方案已生成')}else{if(!t.parsed)return toast('请先解析需求');if(t.shots.some(s=>!['edit','aigc','keep'].includes(s.method)))return toast('请为每个分镜选择一种生成方式');if(t.mode==='replace'&&!t.script.trim())return toast('请填写新口播');if(t.shots.some(s=>s.cuts.length&&s.method!=='keep'&&!s.prompt.trim()))return toast('请补充每个待生成分镜的提示词');if(t.plans.some(p=>!p.trim()))return toast('请补充空白方案');t.batch++;t.review=false;t.sampleConfirmed=false;t.batchDone=false;t.shots.forEach(s=>s.approved=false)}t.running=true;t.progress=0;t.stage=batch?'批量生成中':'样片生成中';t.runLabel=batch?`剩余 ${t.plans.length-1} 条方案分别生成`:'分镜生成中';save();render();const live=t.shots.filter(s=>s.cuts.length);for(const s of live){await new Promise(r=>setTimeout(r,550));t.progress++;if(!batch){s.candidates.forEach(c=>c.selected=false);s.candidates.push({id:Date.now()+s.id,prompt:s.prompt,refs:[...s.refs],selected:true});}if(task()?.id===t.id)render()}t.runLabel='音画合成中';if(task()?.id===t.id)render();await new Promise(r=>setTimeout(r,550));if(batch){for(let n=1;n<t.plans.length;n++)newResult(t,n);t.batchDone=true;t.stage='成片待审核'}else{newResult(t,0,true);t.review=true;t.stage='样片待审核'}t.running=false;t.time=Date.now();save();render();toast(batch?'批量模拟完成，结果已同步资产库':'完整样片模拟完成，请逐镜审核')}
function showPreview(i,clip=false,result=null){const t=result?.t||task(),v=media(t);modal(clip?`细片段 ${i} 预览`:result?`${esc(result.r.name)} ${esc(result.r.current)}`:'视频预览',v?.url?`<video controls src="${esc(v.url)}"></video><p class="muted small">原型播放上传的源视频，用于演示播放器；不会伪装成 AI 生成结果。</p>`:`<div style="width:150px;margin:auto">${art(clip?kind(i):Number(i)||0)}</div><p class="muted" style="text-align:center">这是示例插画，没有真实视频文件。上传模板后可演示原片播放。</p>`)}
function candidates(i){const s=shot(i);modal(`分镜 ${i+1} 候选版本`,s.candidates.map((c,n)=>`<div class="history-item row between"><div><b>候选 ${n+1} ${c.selected?'· 已选用于合成':''}</b><p class="muted small">保留本次提示词与图片引用快照</p></div><div><button data-action="preview" data-i="${i}">预览</button><button data-action="chooseCandidate" data-i="${i}" data-n="${n}">选用</button></div></div>`).join('')||'暂无候选')}
function history(id){const {r}=resultById(id);modal(`${esc(r.name)} · 历史版本`,r.versions.map(v=>`<div class="history-item row between"><div><b>${v.name} ${r.current===v.name?'· 当前版':''}</b><p class="muted small">${v.status} · ${new Date(v.created).toLocaleString('zh-CN')}</p></div><div><button data-action="resultPreview" data-i="${id}">预览源视频</button><button data-action="restore" data-id="${id}" data-version="${v.name}">${r.current===v.name?'当前版本':'使用此版本'}</button></div></div>`).join(''))}
function checkCompletion(t){if(t.results.length&&t.results.every(r=>['已定稿','废弃'].includes(r.status))&&!t.running)t.stage='已完成';else if(t.results.length)t.stage='成片待审核'}
document.addEventListener('input',e=>{const d=e.target.dataset,f=d.field;if(!f)return;if(f==='taskQuery'){taskQuery=e.target.value;render();return}if(f==='assetQuery'){assetQuery=e.target.value;render();return}if(['brief','script'].includes(f)){const t=task();if(t.parsed&&t.parsedBrief===undefined){t.parsedBrief=t.brief;t.parsedScript=t.script;t.parsedMode=t.mode}t[f]=e.target.value;t.requirementDirty=!!t.parsed&&(t.brief!==t.parsedBrief||t.script!==t.parsedScript||t.mode!==t.parsedMode);if(typeof refreshRequirementFeedback==='function')refreshRequirementFeedback(t);/* The inline reference chooser preserves the active caret. */}else if(f==='plan'){task().plans[+d.i]=e.target.value}else if(['prompt','ai','description','person','scene','speech','caption'].includes(f)){const s=shot(+d.i);s[f]=e.target.value;if(f==='prompt'){s.manual=true;/* The inline reference chooser preserves the active caret. */}if(['description','person','scene','speech'].includes(f)&&task().parsed&&!s.manual)s.prompt=promptFor(s)}save()});
document.addEventListener('change',e=>{const d=e.target.dataset,f=d.field;if(f==='mode'){task().mode=e.target.value;task().parsed=false;task().shots.forEach(s=>{if(task().mode==='replace'&&s.method==='edit')s.method='aigc'});touch();render()}if(f==='method'){const s=shot(+d.i);s.method=e.target.value;s.undoPrompt=s.prompt;s.prompt=s.method==='keep'?'':task().demoFamily&&s.specKey?singleMethodPrompt(s):promptFor(s);s.manual=true;s.refs=s.method==='keep'?[]:s.refs;touch();render()}if(f==='mergeCutSelect'){e.target.checked?cutSelection.add(+d.n):cutSelection.delete(+d.n);render()}if(f==='cutSelect'){const n=+d.n;if(e.target.checked)draftCuts.push(n);else draftCuts=draftCuts.filter(x=>x!==n);drawCutsModal()}if(f==='resultCheck'){e.target.checked?selectedResults.add(d.id):selectedResults.delete(d.id);render()}if(f==='status'){const {t,r}=resultById(d.id);if(r.sample&&e.target.value==='已定稿'&&!t.sampleConfirmed){render();return toast('样片须在工作台逐镜审核并确认整片')}r.status=e.target.value;r.versions.find(v=>v.name===r.current).status=r.status;t.time=Date.now();checkCompletion(t);save();render()}if(d.upload)upload(e.target.files,d.upload)});
async function upload(files,mode){for(const file of files){if(mode==='template'&&!file.type.startsWith('video/')){toast('请选择本地视频文件');continue}if(mode!=='template'&&!file.type.startsWith('image/')){toast('参考素材仅支持图片');continue}if(!/^(image|video)\//.test(file.type)){toast('请选择图片或视频文件');continue}const type=file.type.startsWith('image')?'image':'video',url=URL.createObjectURL(file),id='a'+Date.now()+Math.random().toString(16).slice(2);if(mode==='template'){const name=file.name.replace(/\.[^.]+$/,'');const t=makeTask('t'+Date.now(),name,Date.now());t.folder=currentFolder;state.folders.find(f=>f.id===t.folder).open=true;state.tasks.unshift(t);active=t.id;view='work';task().stage='解析完成 · 演示模板';state.assets.push({id,name:file.name,type,url,source:name,kind:0});t.assets.push(id);t.assets.push('a1','a2');toast('模板已上传；分镜解析为演示内容')}else{state.assets.push({id,name:file.name,type,url,source:task()?.name||'共享素材库',kind:0});task()?.assets.push(id);toast(task()?'素材已添加到当前任务':'图片已上传到共享素材库')} }save();$('#dialog').close();render()}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const d=b.dataset,a=d.action,i=+d.i,t=task();switch(a){case 'undoTaskMove':{const prev=state.undoTaskMove;if(prev){const moved=state.tasks.find(t=>t.id===prev.id);if(!moved){delete state.undoTaskMove;save();render();break}moved.folder=prev.folder;moved.time=prev.time;currentFolder=prev.folder;state.folders.find(f=>f.id===prev.folder).open=true;delete state.undoTaskMove;save();render();toast('已撤销任务移动')}break}case 'toggleMaterials':materialsOpen=!materialsOpen;render();break;case 'view':view=d.view;selectedResults.clear();render();break;case 'task':active=d.id;currentFolder=task().folder;view='work';cutSelection.clear();editResult=null;save();render();break;case 'new':modal('新建',`<div class="new-options"><button data-action="newTask">＋ 新建任务<small>上传原视频，开始复刻</small></button><button data-action="newFolder">▱ 新建文件夹<small>按品牌或业务管理任务</small></button></div>`);break;case 'folder':{const f=state.folders.find(f=>f.id===d.id);f.open=!f.open;currentFolder=f.id;save();render();break}case 'newFolder':modal('新建文件夹','<label>项目名称<input id="folder-name" placeholder="例如：核桃编程、医美、牙医" style="width:100%"></label>','<button data-action="close">取消</button><button class="primary" data-action="createFolder">创建文件夹</button>');break;case 'createFolder':{const name=$('#folder-name').value.trim();if(!name)return toast('请输入项目名称');if(state.folders.some(f=>f.name===name))return toast('项目名称已存在');const f={id:'f'+Date.now(),name,open:true};state.folders.push(f);currentFolder=f.id;save();$('#dialog').close();render();toast('文件夹已创建');break}case 'newTask':uploadTaskModal();break;case 'createLinkTask':createLinkTask();break;case 'close':$('#dialog').close();break;case 'fillDemo':t.brief=FAMILY_DEMO_BRIEF;t.parsed=false;t.review=false;t.sampleConfirmed=false;t.stage='需求待解析';t.shots.forEach(s=>{s.prompt='';s.method='pending';s.refs=[];s.manual=false;delete s.suggestion;delete s.undoPrompt});touch();render();toast('已填入示例需求，解析后填写提示词并确定生成方式');break;case 'parse':parse();break;case 'materials':materialModal(i);break;case 'uploadAssets':materialModal(-1);break;case 'attachAsset':if(!t)return toast('请先新建或恢复一个任务');if(!t.assets.includes(d.id))t.assets.push(d.id);touch();render();toast('素材已添加，输入 @ 可引用');break;case 'unref':if(t.shots.some(s=>s.refs.includes(d.id)))return toast('此素材已被分镜引用，请先移除分镜引用');t.assets=t.assets.filter(x=>x!==d.id);touch();render();break;case 'addMention':if(!t.parsed&&!shot(i)?.independent)return toast('请先解析模糊需求');shot(i).prompt+='@';render();break;case 'mention':{const asset=state.assets.find(a=>a.id===d.id);if(i===-1){t.brief=t.brief.replace(/@$/,'')+'@'+asset.name+' ';}else{const s=shot(i);if(!s.refs.includes(asset.id))s.refs.push(asset.id);const token=t.demoFamily?'@图片'+(s.refs.indexOf(asset.id)+1):'@'+asset.name;s.prompt=s.prompt.replace(/@$/,'')+token+' ';if(t.demoFamily)s.prompt+='\n'+(SEEDANCE_ROLE_LINES[FAMILY_DEMO_ASSETS.findIndex(a=>a.id===asset.id)]||'@图片{n}用于指定主体的外观。').replaceAll('{n}',s.refs.indexOf(asset.id)+1);s.manual=true}touch();render();break}case 'removeMention':{const s=shot(i);if(t.demoFamily){const idx=s.refs.indexOf(d.id)+1;s.undoPrompt=s.prompt;s.prompt=s.prompt.split('\n').filter(line=>!new RegExp('@图片'+idx+'(?![0-9])').test(line)).join('\n').replace(/@图片(\d+)/g,(m,n)=>Number(n)>idx?'@图片'+(Number(n)-1):m);s.manual=true;toast('已解除引用并重排编号，请复核涉及该素材的句子')}else s.prompt=s.prompt.replace('@'+state.assets.find(a=>a.id===d.id).name,'');s.refs=s.refs.filter(x=>x!==d.id);touch();render();break}case 'plans':plansModal();break;case 'addPlan':t.plans.push('');save();plansModal();break;case 'deletePlan':t.plans.splice(i,1);save();plansModal();break;case 'polish':{const s=shot(i);if(!s.prompt.trim())return toast('先解析需求或填写提示词');s.undoPrompt=s.prompt;s.undoManual=s.manual;s.prompt=s.prompt.replace(/\n{3,}/g,'\n\n').trim()+'\n\n【一致性核对】\n按上文逐项绑定的素材保持主体身份、道具归属与声音连续。'+(s.method==='edit'?'原动作与未修改区域沿用@视频1。':'按上文画面描述生成，不引用视频编辑母版。');s.manual=true;delete s.suggestion;touch();render();toast('提示词已润色，可撤销');break}case 'apply':{const s=shot(i);s.undoPrompt=s.prompt;s.prompt=s.suggestion;s.manual=true;delete s.suggestion;touch();render();break}case 'undoPrompt':{const s=shot(i);s.prompt=s.undoPrompt;if(s.undoManual!==undefined)s.manual=s.undoManual;delete s.undoPrompt;delete s.undoManual;touch();render();break}case 'discard':delete shot(i).suggestion;save();render();break;case 'toggleCuts':shot(i).open=!shot(i).open;save();render();break;case 'moveCuts':cutsModal(i);break;case 'addShot':dialogCtx={type:'newCuts',i:-1};draftCuts=[];drawCutsModal();break;case 'selectCuts':{const s=shot(i),all=s.cuts.every(n=>cutSelection.has(n));s.cuts.forEach(n=>all?cutSelection.delete(n):cutSelection.add(n));render();break}case 'mergeNew':{const selected=shot(i).cuts.filter(n=>cutSelection.has(n));if(selected.length<2)return;snapshotCuts();createShotFromCuts(selected,i+1);contentChanged();render();toast('已合并为新分镜，原分镜同步更新');break}case 'moveShot':{const target=i+Number(d.direction);if(target<0||target>=t.shots.length)return;snapshotCuts();const [moved]=t.shots.splice(i,1);t.shots.splice(target,0,moved);reindexShots();contentChanged();render();toast('分镜顺序已更新');break}case 'deleteShot':modal(`删除分镜 ${i+1}？`,`该分镜的 ${shot(i).cuts.length} 个片段会移出成片，可从“新增分镜”再次选择，也可撤销。`,`<button data-action="close">取消</button><button class="danger" data-action="confirmDeleteShot" data-i="${i}">删除分镜</button>`);break;case 'confirmDeleteShot':snapshotCuts();t.excluded.push(...shot(i).cuts);t.shots.splice(i,1);reindexShots();contentChanged();$('#dialog').close();render();toast('分镜已删除，可撤销');break;case 'commitCuts':{if(!draftCuts.length)return;snapshotCuts();if(dialogCtx.type==='newCuts')createShotFromCuts(draftCuts,t.shots.length);else{const s=shot(dialogCtx.i);t.shots.forEach(x=>x.cuts=x.cuts.filter(n=>!draftCuts.includes(n)));s.cuts.push(...draftCuts);s.cuts.sort((a,b)=>a-b);s.parts=[];if(s.method==='mixed')s.method='edit';s.manual=true;s.needsReview=true;t.excluded=t.excluded.filter(n=>!draftCuts.includes(n));t.shots=t.shots.filter(s=>s.cuts.length);reindexShots()}contentChanged();$('#dialog').close();render();toast('片段已更新，可撤销');break}case 'removeCut':{const s=shot(i);snapshotCuts();s.cuts=s.cuts.filter(n=>n!==+d.n);t.excluded.push(+d.n);s.parts=[];if(s.method==='mixed')s.method='edit';s.manual=true;s.needsReview=true;cutSelection.delete(+d.n);t.shots=t.shots.filter(x=>x.independent||x.cuts.length);reindexShots();contentChanged();render();toast('此片段不再进入成片，可撤销');break}case 'undoCuts':if(t.undoCuts?.shots){t.shots=t.undoCuts.shots;t.excluded=t.undoCuts.excluded;delete t.undoCuts;cutSelection.clear();reindexShots();contentChanged();render();toast('已撤销分镜调整')}break;case 'preview':case 'original':case 'samplePreview':showPreview(i||0);break;case 'cutPreview':if($('#dialog').open&&dialogCtx.type==='cuts')toast(`片段 ${i}：${secs(i)} 秒，${kind(i)===0?'人物介绍':kind(i)===1?'积木车展示':'手机演示'}（演示预览）`);else showPreview(i,true);break;case 'assetPreview':{const asset=state.assets.find(a=>a.id===d.i);modal(esc(asset.name),asset.builtin?`<div class="asset-detail">${assetVisual(asset)}</div><p>${esc(asset.tags||'')}</p><p class="muted small">${asset.role==='原片记录'?'原片记录：标记保留段落，不作为AI重绘参考。':'可通过 @'+esc(asset.name)+' 引用；商品图片约束包装，人物图片约束身份。'}</p>`:asset.url?(asset.type==='image'?`<img alt="${esc(asset.name)}" src="${esc(asset.url)}" style="max-width:100%;max-height:60vh">`:`<video src="${esc(asset.url)}" controls></video>`):art(asset.kind));break}case 'generate':generate();break;case 'approveShot':shot(i).approved=d.value==='true';t.sampleConfirmed=false;touch();render();break;case 'confirmSample':if(t.shots.some(s=>s.cuts.length&&!s.approved))return;t.sampleConfirmed=true;t.stage=t.plans.length>1?'样片已确认 · 可批量生成':'已完成';const sample=[...t.results].reverse().find(r=>r.sample&&r.batch===t.batch);if(sample){sample.status='已定稿';sample.versions.find(v=>v.name===sample.current).status='已定稿'}touch();render();toast('样片已确认');break;case 'batch':generate(true);break;case 'goFinished':view='assets';assetTab='finished';render();break;case 'locate':$('#shot-'+i).scrollIntoView({behavior:'smooth',block:'center'});break;case 'redo':{const s=shot(i);if(!s.prompt.trim())return toast('请填写提示词');s.candidates.forEach(c=>c.selected=false);s.candidates.push({id:Date.now(),prompt:s.prompt,refs:[...s.refs],selected:false});s.approved=false;t.sampleConfirmed=false;save();render();candidates(i);toast('新候选已生成（模拟），选择后再更新整片');break}case 'candidates':candidates(i);break;case 'chooseCandidate':{const s=shot(i);s.candidates.forEach((c,n)=>c.selected=n===+d.n);s.approved=false;t.sampleConfirmed=false;const r=editResult?resultById(editResult)?.r:[...t.results].reverse().find(r=>r.sample&&r.batch===t.batch);if(r){const name='v'+(r.versions.length+1);r.versions.push({name,status:'待审核',created:Date.now()});save();$('#dialog').close();history(r.id);toast('待审核新版本已合成，旧当前版保留')}else{$('#dialog').close();render()}break}case 'assetTab':assetTab=d.tab;assetFilter='全部';selectedResults.clear();render();break;case 'filter':assetFilter=d.filter;selectedResults.clear();render();break;case 'resultPreview':showPreview(0,false,resultById(d.i));break;case 'history':history(d.id);break;case 'restore':{const {t:owner,r}=resultById(d.id);r.current=d.version;r.status=r.versions.find(v=>v.name===d.version).status;owner.sampleConfirmed=false;checkCompletion(owner);save();history(d.id);render();toast('当前版本已切换，历史版本保留');break}case 'returnResult':{const x=resultById(d.id);active=x.t.id;editResult=x.r.id;view='work';render();toast('已返回所属任务，可修改单镜并重做');break}case 'selectVisible':allResults().filter(r=>(assetFilter==='全部'?r.status!=='废弃':r.status===assetFilter)&&`${r.taskName} ${r.name}`.includes(assetQuery)).forEach(r=>selectedResults.add(r.id));render();break;case 'bulkApprove':{let done=0,skip=0;selectedResults.forEach(id=>{const {t:owner,r}=resultById(id);if(r.sample&&!owner.sampleConfirmed){skip++;return}r.status='已定稿';r.versions.find(v=>v.name===r.current).status='已定稿';checkCompletion(owner);done++});save();render();toast(`已定稿 ${done} 条${skip?`；${skip} 条样片需先逐镜审核确认`:''}`);break}case 'download':{const files=[...selectedResults].map(id=>resultById(id)).map(({t,r})=>({task:t.name,plan:r.name,version:r.current,status:r.status}));const blob=new Blob([JSON.stringify({note:'交互原型演示说明；不包含真实生成视频。',files},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='复刻大师_演示交付说明.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已下载演示说明；真实 MP4 / ZIP 需接入生成服务');break}case 'reset':modal('重置演示？','将清除本原型保存的任务和编辑内容，不影响你的本地文件。','<span></span><div><button data-action="close">取消</button><button class="danger" data-action="resetConfirm">重置</button></div>');break;case 'resetConfirm':localStorage.removeItem('replica-workbench-v3');location.reload();break}});
